{"type":"assistant","message":{"model":"claude-haiku-5-5","id":"msg_011CgJYw4BGsAwi1XsdihqtF","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_011RqbJYfJXXp8CxfJVb82Ch","name":"mcp__falkon__list_commits","input":{"repo":"github.com/openmrs/openmrs-esm-form-engine-lib","since":"2026-04-16","path":"src","perPage":100},"caller":{"type":"direct"}}],"container":null,"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":2,"cache_creation_input_tokens":294,"cache_read_input_tokens":13406,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":294},"output_tokens":2,"service_tier":"standard","inference_geo":"global","speed":"standard"},"input_transformations":[],"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"2c8e374f-6e9f-4b78-9042-e4ee8bd8b73a","uuid":"549b2597-6b67-4fd5-a004-e5f7903066e1","timestamp":"2026-10-23T04:38:45.363Z","request_id":"req_011CgJYw3sfRykVTDNvvtMPC","wire_tool_inputs":{"toolu_011RqbJYfJXXp8CxfJVb82Ch":{"repo":"github.com/openmrs/openmrs-esm-form-engine-lib","since":"2026-04-16","path":"src","perPage":100}},"tool_use_meta":[{"id":"toolu_011RqbJYfJXXp8CxfJVb82Ch","display_name":"List Commits","server_display_name":"falkon-mcp-server","tool_name":"list_commits"}]}
{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_011RqbJYfJXXp8CxfJVb82Ch","type":"tool_result","content":[{"type":"text","text":"{\"commits\":[{\"hash\":\"b0d8fd2e9a0c68f2c72b2415b6dbf351b6e92c30\",\"date\":\"2026-10-13T16:17:05+05:30\",\"message\":\"(fix) O3-5847: Stop unchanged obs values from creating duplicate obs (#842)\",\"refs\":\"\",\"body\":\"When transformFieldValue received a value equal to the stored obs, it fell\\nthrough to constructObs and submitted a new obs without a uuid, so every save\\nadded a duplicate. It now returns early and submits nothing for an unchanged\\nvalue on a stored obs.\\n\\nhasPreviousObsValueChanged compared date fields with dayjs diff on 'D', which\\ndayjs does not support and treats as milliseconds. It now formats both values\\nwith formatDateByPickerType, the function used for submission, and compares the\\nstrings, so a date counts as changed only when the submitted value changes.\\nformatDateByPickerType falls back to the transformer's defaults when a field\\nhas no datePickerFormat.\\n\\ngetPreviousValue no longer makes the previous encounter's obs the field's own\\nobs, so changing or clearing a previous value in a new encounter no longer\\nupdates or voids the previous encounter's obs.\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"c79bf029d7ce3c51921276c656bea05e82780f4b\",\"date\":\"2026-10-13T15:47:45+05:30\",\"message\":\"(BREAKING) O3-5847: Stop datetime obs shifting a day across timezones (#838)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"ea6bcc897fc95c797df7dbd15abe13b07bbff92f\",\"date\":\"2026-10-13T12:29:56+03:00\",\"message\":\"(fix) Display validation errors for checkbox groups (#840)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Samuel Muli\",\"authorEmail\":\"136758902+Samstar10@users.noreply.github.com\"},{\"hash\":\"c0c4765b1b4224ba9ea3499c4cc77398afa50a73\",\"date\":\"2026-10-12T15:18:37-04:00\",\"message\":\"(fix) Post submission helper should not use eval() (#843)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"129c1f7fd78a83d1b8958ae6dcaa7fe7b51eb143\",\"date\":\"2026-10-08T01:13:57+05:00\",\"message\":\"(fix) O3-6045: Use WHO girls' height-for-age reference and cover month after age 5 (#834)\",\"refs\":\"\",\"body\":\"* (fix) O3-6045: Use WHO girls' height-for-age reference and cover month after age 5\\n\\nhfa_girls_5_above.json was a copy of the boys' table, so girls aged 5 to 17 got height-for-age z-scores against boys' heights. It is now replaced with the table generated from WHO Growth Reference 2007 girls' height-for-age data.\\n\\ngetHeightForAgeRef now uses the under-5 table through day 1,856, where that table ends, and the 5 to 19 year table from month 61 onwards. getBmiForAgeRef uses the 5 to 19 year table from month 61 after day 1,856, so children in the month after their fifth birthday receive valid evaluations instead of null.\\n\\nAdded tests validating table divergence between boys and girls, spot-checking WHO medians against published values, and verifying age transitions.\\n\\n* (fix) O3-6045: Guard weight-for-height scores against invalid birth dates\\n\\nReturn null when the patient's age is unknown instead of selecting an\\nunder-five reference table through the null < 5 comparison.\\n\\nCover missing and invalid birth dates for both sexes in the reference\\nservice and expression helper tests, with the weight-for-height tables\\nloaded before checking the guards.\",\"authorName\":\"Faisal Mehmood\",\"authorEmail\":\"sfm7776@gmail.com\"},{\"hash\":\"bca651cc37683143cadc43e8301cecf806b29738\",\"date\":\"2026-10-07T23:09:52+03:00\",\"message\":\"(test) Wait for the z-score tables before querying the height field (#837)\",\"refs\":\"\",\"body\":\"The first test in zscore-loading.test.tsx pays the cold dynamic import of the WHO\\nreference tables. findByRole gives up after one second, and on the CI runner the\\nimport sometimes takes longer than that, so the test fails with \\\"Unable to find\\nrole=spinbutton\\\" while the form is still showing its loader. It failed that way on\\nmain at 6a5b489 and on both CI runs of #834.\\n\\nThe test now awaits the promise loadZScoreReferences returned before looking for\\nthe height field, so the one-second query timeout starts after the tables are\\nloaded. The later tests in the file run against warm imports, which is why only\\nthis one flakes. With the import delayed by 1.5 seconds locally, the test fails\\nthe same way without this change and passes with it.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"6a5b489b47c58f526f9988624c0bf349ec5b75ad\",\"date\":\"2026-10-07T14:56:38+03:00\",\"message\":\"(fix) O3-6048: Accept numeric string height in calcWeightForHeightZscore (#832)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"solomonfortune\",\"authorEmail\":\"solomonbuwule@gmail.com\"},{\"hash\":\"79f2c23a1a4b3f45103fcd6f63746c87afa6e9fb\",\"date\":\"2026-10-06T22:39:38+05:00\",\"message\":\"(fix) O3-6046: Return null when height is outside reference table or no reference applies (#830)\",\"refs\":\"\",\"body\":\"* (fix) O3-6046: Return null when height is outside reference table or no reference applies\\n\\n* Restore dropped weight-for-height test case\\n\\nThe male age4 case for 95.7 cm and 14 kg was removed along with the\\nout-of-range rows, but the height is inside the reference table and\\nthe expected z-score of '-1' still holds. The matching female case\\nwas kept.\",\"authorName\":\"Faisal Mehmood\",\"authorEmail\":\"sfm7776@gmail.com\"},{\"hash\":\"fcf1b2562d60389dbf88c5383c2d4237d9d1ff8a\",\"date\":\"2026-10-05T15:02:05+03:00\",\"message\":\"(fix) O3-6025: Load z-score tables only when a form needs them (#824)\",\"refs\":\"\",\"body\":\"* (fix) Load z-score reference tables only for forms that use them\\n\\nThe WHO reference tables behind the z-score helpers are about 1.3 MB of JSON, and zscore-service imported all eight of them statically. The form engine app imports registerExpressionHelper from the library's entry at startup, so the tables ended up in its startup chunk, and every form open downloaded and parsed them whether or not the form used a z-score helper.\\n\\nEach table is a dynamic import now. useProcessorDependencies loads the tables for the z-score helpers a form's schema mentions, alongside the processor's own dependencies, so they're in place before initial values or any expression is evaluated. The helpers stay synchronous, because the expression evaluator doesn't await a helper's result before applying an operator to it. getZRefByGenderAndAge is split into one function per reference, so each helper only reads the tables it needs. If a table fails to load, the form still opens, the error is reported, and the helpers that need it return null.\\n\\nuseProcessorDependencies also reports loading from the first render. Once a form has opened, its field adapters and concepts are cached, so initial values could otherwise be computed before the dependencies had started loading.\\n\\nIn esm-form-engine-app the startup chunks go from 1,189 KiB to 382 KiB, or from 301 KiB to 114 KiB gzipped.\\n\\n* (fix) Wait for form dependencies before evaluating growth rules\\n\\n* Keep form state when the schema object changes\\n\\nResetting the form session whenever formJson was a new object wiped\\nentered values in the patient chart. esm-form-engine-app passes a new\\nschema object on every render, and it re-renders once the form is\\nmarked dirty, so the first edit was lost.\\n\\nDrop the session reset in FormFactoryProvider and stop\\nuseProcessorDependencies reloading on a new formJson object. The form\\nbuilder already remounts FormEngine when its schema changes, so no\\nconsumer relies on replacing a mounted schema.\\n\\n* fix: Wait for every subform before allowing submission\\n\\nTrack pending dependencies by form instance so a ready sibling cannot clear another subform’s loading state. Remove the instance from the pending set when it unmounts.\\n\\nCover pending and failed subform dependencies, retry, required-field validation and saving all subforms after recovery.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"0e1edc234479890d45bc09e67b2ee25befc1c803\",\"date\":\"2026-10-05T14:52:41+03:00\",\"message\":\"(fix) O3-6027: Clear order and diagnosis submissions on every write (#826)\",\"refs\":\"\",\"body\":\"* (fix) Clear order and diagnosis submissions on every write\\n\\nOrdersAdapter and EncounterDiagnosisAdapter now clear the field's\\nsubmission at the start of transformFieldValue, the same way ObsAdapter\\nalready does.\\n\\ngracefullySetSubmission only sets values and never clears them, so a\\nnewValue from an earlier write stayed on the field after it was\\ncleared. On a new encounter, selecting an order or diagnosis and then\\nclearing the field still submitted it. On an edited encounter, swapping\\na stored order or diagnosis for another value and then clearing the\\nfield still submitted the swapped value: a NEW order alongside the\\nvoid, or an edit of the stored diagnosis to the swapped concept.\\nClearing first means nothing is submitted for a new encounter and only\\nthe void goes out for an edited one.\\n\\neditOrder no longer needs its own clearSubmission call when the value\\nmatches the stored order, since the submission is already empty.\\n\\n* Fixup\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"ebb02b719931d121419669b531b6e05c77f515e9\",\"date\":\"2026-10-02T21:57:25+03:00\",\"message\":\"(fix) O3-6030: Keep hidden obs group members, orders and diagnoses out of submissions (#822)\",\"refs\":\"\",\"body\":\"* (fix) Keep hidden obs group members, orders and diagnoses out of submissions\\n\\nHide logic only kept hidden top-level obs out of the encounter payload.\\nHidden obs group members, test orders and diagnoses kept whatever value\\nwas entered before the field was hidden, so they were still submitted\\neven though the form no longer showed them.\\n\\nprocessObsGroup now skips hidden members and, in edit mode, voids their\\nstored obs, the same way top-level obs are handled. It reads each\\nmember's visibility and stored obs from the flattened form field,\\nbecause hide evaluation and hydration update that copy rather than the\\none held in the group's questions. prepareOrders and prepareDiagnosis\\nnow skip hidden fields.\\n\\n* Evaluate hide logic for repeated field instances\\n\\nRows added to a repeating field kept their hidden state from when they\\nwere created, so hiding a repeating test order, diagnosis or obs group\\nmember left its extra rows in the encounter payload. Extra group rows\\nalso stayed visible in the form.\\n\\nfindFieldSection looks up the field's page through meta.pageId, which\\nrepeated instances don't carry because cloneRepeatField replaces their\\nmeta. Reading sections off the missing page threw inside the\\nfieldDependents loop in handleFieldLogic, so none of the repeated\\ninstances had their hide expression re-evaluated. It now returns\\nundefined when the page isn't found, which skips the section visibility\\nupdate for repeated instances since they aren't in the form schema.\\n\\n* (fix) Preserve pending deletions for hidden orders and diagnoses\\n\\nFiltering hidden fields out of encounter submissions discarded explicit deletions when a previously cleared field became hidden. Keep pending voided values for hidden orders and diagnoses while excluding their new values. Leave stored values untouched when no deletion is pending, and preserve existing submission behavior for visible fields.\\n\\n* Skip deleted repeated rows when evaluating field dependents\\n\\nDeleting a repeated row removes it from formFields but leaves its id in\\nthe fieldDependents of any field its hide expression references. The\\nnext change to that field made evaluateFieldDependents read\\nquestionOptions off undefined, which threw and stopped the remaining\\ndependents, including other repeated rows, from being re-hidden.\\n\\nevaluateFieldDependents now skips dependent ids that are no longer in\\nformFields.\\n\\n* Keep the stored uuid of nested obs groups\\n\\nprocessObsGroup recursed into nested groups with the copy held in the\\nparent group's questions, which hydration doesn't reach. When a member\\nof a nested group was hidden and nothing else in that group was edited,\\nthe nested group went out without its stored uuid, so the backend\\nwould treat it as a new group rather than update the existing one.\\n\\nThe type check, the recursion and the submission reads now use the\\nflattened form field, the same copy already used for the hidden check.\\nhasSubmittableObs also reuses isFieldHidden instead of repeating the\\ncheck.\\n\\n* Leave hidden swapped orders and diagnoses as they are\\n\\nA swap sets voidedValue alongside newValue, so keeping only voidedValue\\nfor a hidden order turned a replacement into a plain delete: the stored\\norder was voided and nothing replaced it. A hidden diagnosis swapped\\ndirectly was left alone, so the two behaved differently.\\n\\nHidden orders and diagnoses now only submit their voided value when\\nthere's no newValue, which means the field was explicitly cleared.\\nSwapped and reanswered values are left as they are.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"7182a63a48cbf311fb083116b767ad3dc10e3f88\",\"date\":\"2026-09-28T23:31:53+05:30\",\"message\":\"(fix) O3-5963: Improve contrast and anchoring of remove-attachment btn (#816)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Sathieskumar Sudeshkar\",\"authorEmail\":\"sudeshkar008sk@gmail.com\"},{\"hash\":\"dc5422465be8c3ccf4dba4d60977aeb724365b65\",\"date\":\"2026-09-25T14:48:46+03:00\",\"message\":\"(fix) Avoid redundant searches and duplicate field processing (#800)\",\"refs\":\"\",\"body\":\"* fix: debounce searchable select requests\\n\\nKeep the debounce stable across renders and cancel superseded searches.\\nIgnore obsolete responses and cover request lifetime with regression tests.\\n\\n* fix: process field input changes once\\n\\nSkip the watcher echo for values already processed by controls while\\nretaining programmatic updates, array inputs, and historical-value reuse.\\n\\n* fix: stop searchable select requests after selection\\n\\nRead the selected value through a ref so selecting an item does not\\nrestart a search for the previous term. Cancel pending searches and\\ninvalidate in-flight responses when a selection is made.\\n\\nCover synonym matches, pending searches, and responses after selection.\\n\\n* test: tidy the searchable select request tests\\n\\nMove the selection tests into the shared describe block, group the imports,\\nand separate setup, actions, and assertions with blank lines. Drop the manual\\ncleanup call since auto-cleanup already runs, type the wrapper's props as\\nFormField, and pull the repeated combobox change event into a helper.\\n\\nNote why the file drives the input with fireEvent: userEvent waits on a\\nsetTimeout that testing-library only advances under jest's fake timers, so it\\nnever resolves while vitest's fake timers are installed.\\n\\n* fix: read the current selection from form state\\n\\nUse getValues when preserving the selected item in search results. Remove the effect-backed value ref so result handling reads the current form value directly.\\n\\n* fix: validate values entered after unspecified\\n\\nClear the unspecified flag before validating a nonempty value and keep the checkbox synchronized with that flag. This lets the first value run through validation once without relying on effect ordering.\\n\\nCover entering an invalid value in enter and edit modes, correcting it, and reusing a historical value after marking the field unspecified.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"ae1b2b294c2e1a7635bb05f9ed803d7a769496f4\",\"date\":\"2026-09-22T15:51:00-04:00\",\"message\":\"(test) Add tests to cover form submission orchestration (#812)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"8a6e7ea9131cfef56a1c3680bbba47d11bf710fb\",\"date\":\"2026-09-21T18:32:15+03:00\",\"message\":\"(chore) O3-5924: Initialise the root form ref (#810)\",\"refs\":\"\",\"body\":\"Pass undefined explicitly when creating the root form ref. Keep its existing initial value and form registration behaviour while preparing for React 19 types.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"949ad19f6abe33f84a56f623690821c95068628c\",\"date\":\"2026-09-09T17:59:20-04:00\",\"message\":\"(fix) Form engine shouldn't create global CSS rules (#798)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"ad9786412cd423a86c54f889b4e87cf6cf59d61e\",\"date\":\"2026-09-09T12:53:22-04:00\",\"message\":\"(fix) Reduce re-render churn in FormProcessorFactory (#670)\",\"refs\":\"\",\"body\":\"* (fix) Re-write some core hooks in the form-processor-factory to reduce churn\\n\\nIn the FormProcessorFactory, there's serious potential for render\\ncascades from the combinations of `useEffect()` and `setState()` that\\nthen trigger additional `useEffect()` and `setState()` calls. This\\ncommit switches to more aggressively caching some of these key hooks so\\nthat there's less potential for these cascade to lead to catastrophic\\nreloading issues.\\n\\n* Reduce churn in processor context\\n\\nThis is basically done by splitting the processor context into a \\\"static\\\"\\npart that is derived from the form itself and a \\\"dynamic\\\" part that may\\nbe updated by components downstream of the FormProcessorFactory. This\\nmostly should optimize things so that components that depend on the\\nprocessor context should mostly get stable objects, assuming they\\ncorrectly use the properties of the processor.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"954cee04af4f957d9cea4f57137a63d5a793d021\",\"date\":\"2026-09-09T09:26:06-04:00\",\"message\":\"(feat) Wrap FormEngine in Suspense boundary (#797)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"a6f911cf3612608cac9649229396e0ebc92ae8ba\",\"date\":\"2026-08-20T15:59:32-04:00\",\"message\":\"(test) Add \\\"golden schemas\\\" for encounter payloads (#787)\",\"refs\":\"\",\"body\":\"Co-authored-by: Dennis Kigen <kigen.work@gmail.com>\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"575343c08c8430e8d9de7cd4c137db6a3256c3c4\",\"date\":\"2026-08-19T14:15:05-04:00\",\"message\":\"(test) Create \\\"golden schemas\\\" for Form Schema operations (#784)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"4db319f4ec64190c6197330675a447dd0121f6df\",\"date\":\"2026-08-14T17:42:14-04:00\",\"message\":\"(test) Add scaffolding for better testing (#783)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"fed294cb652b1873f64a738b8b5b7b9424b93189\",\"date\":\"2026-08-12T11:06:00+03:00\",\"message\":\"(chore) Adopt @openmrs/eslint-config and ESLint 9 (#779)\",\"refs\":\"\",\"body\":\"* (chore) Adopt @openmrs/eslint-config and ESLint 9\\n\\nLint config moves to a flat eslint.config.mjs that spreads\\n@openmrs/eslint-config 2.0.0, replacing .eslintrc and .eslintignore. eslint\\nmoves from 8.57 to ^9.39.0 and the --ext flag goes away, since flat config\\nmakes it redundant. The .d.ts ignore is kept, and dist and coverage are\\nnamed explicitly.\\n\\nComparing the effective rule sets before and after, six rules would have\\nbeen lost, so the overlay enforces them again: ban-ts-comment,\\ntriple-slash-reference, no-extra-boolean-cast, no-prototype-builtins,\\nno-unsafe-optional-chaining and no-useless-escape. This repo disabled\\nban-types deliberately, so the rules typescript-eslint v8 split it into stay\\noff, unlike other repos in this migration.\\n\\nThe old config also loaded type information through parserOptions.project\\nwhile enabling no type-aware rules, so that cost goes away with it. Four dev\\ndependencies go with the plugins the shared config provides, including\\neslint-plugin-jsx-a11y, which was declared but never referenced.\\n\\nThe shared config lints tests with testing-library and jest-dom for the\\nfirst time here, which reported 97 problems across the test suite. Sixteen\\nwere autofixes. no-unused-expressions found a real one:\\nexpect(...).toBeInTheDocument was missing its call, so that assertion never\\nran. It passes now that it does. The rule keeps reporting, with\\nallowShortCircuit set, because `x && f()` as a statement is an idiom here.\\n\\nThe remaining 76 are no-unnecessary-act, render-result-naming-convention\\nand no-manual-cleanup. Those need the tests reworked rather than\\nreformatted, so they are off for test files until that happens, and the rest\\nof testing-library applies.\\n\\n__mocks__/index.ts loads JSON fixtures with require(). The shared config\\nexempts __mocks__/**/*.js from no-require-imports but these mocks are\\nTypeScript, so the exemption is repeated here for the directory.\\n\\n* Keep ESLint config out of next updates\\n\\nReplace the @openmrs wildcard with the packages this repository actually tracks on the next tag. This prevents the stable-only ESLint config from breaking the scheduled dependency update workflow.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"a9fdbfc0f5c2a09368c3fb6e777fc3c274629f76\",\"date\":\"2026-07-16T16:02:24+03:00\",\"message\":\"(fix) Only render diagnosis code span when a code exists\",\"refs\":\"\",\"body\":\"Follow-up to #767. Diagnoses without a terminology mapping rendered an\\nempty code span with a reserved 4rem column, indenting their labels to\\nmatch coded entries. Render the code span conditionally instead so\\ncodeless diagnoses display without the placeholder gap.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"208fcc7720fc4f0ca48efb721cf74e7850af2a32\",\"date\":\"2026-07-16T10:03:19+03:00\",\"message\":\"(feat) O3-5815: Show ICD-11 codes next to diagnoses (#767)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"242dbacbaa26c6d6d43f2c12efddda8ed319b99c\",\"date\":\"2026-06-22T20:53:50+05:30\",\"message\":\"(fix) Inline obs date and comment not saved when field visibility is toggled (#759)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"12c24b6731b62e0993ae8ecbe666b13785f71f6e\",\"date\":\"2026-06-12T12:11:44+03:00\",\"message\":\"(fix) O3-5735: Only send default encounter datetimes for stopped visits\",\"refs\":\"\",\"body\":\"PR #756 made new encounters always submit an explicit encounterDatetime,\\nfalling back to the client-clock session date. On browsers running ahead\\nof server time this produces a future datetime that the backend rejects\\nwith Encounter.datetimeShouldBeBeforeCurrent, breaking form submissions\\nin active visits (caught by patient-chart's clock-skew e2e test).\\n\\nRestore the previous behavior for active visits and visit-less encounters:\\nomit encounterDatetime so the backend defaults it to server time. Keep\\nsending the visit-window-clamped session date for stopped visits, which\\nis the retrospective data entry case O3-5735 fixed.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"b99cb4c27946bf936dce89d37baebe31720f8ef8\",\"date\":\"2026-06-11T23:02:01+03:00\",\"message\":\"(fix) O3-5735: Keep default encounter datetimes within the visit window during retrospective data entry (#756)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"bda295eac9755a4df1c22c9c024ea987ccf4d339\",\"date\":\"2026-05-14T01:18:07+03:00\",\"message\":\"(feat) O3-5660: Encounter provider field should auto-fill with current session provider on new forms (#740)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Donald Kibet\",\"authorEmail\":\"chelashawdonald@yahoo.com\"},{\"hash\":\"2204ac05b44795dec06b132c0d15ca1b010bcd95\",\"date\":\"2026-05-13T16:35:49+03:00\",\"message\":\"(chore) Migrate from jest to vitest (#742)\",\"refs\":\"\",\"body\":\"* (chore) Migrate from jest to vitest\\n\\nSwap the test runner from jest to vitest, aligning form-engine-lib\\nwith the patterns adopted across the rest of the O3 apps.\\n\\n- Replace jest, @swc/jest, jest-cli, jest-environment-jsdom, and\\n  @types/jest with vitest, @vitest/coverage-v8, jsdom, and cross-env.\\n  Bump @testing-library/dom (9.x to 10.x), @testing-library/jest-dom\\n  (6.4 to 6.8), and @testing-library/react (14.x to 16.x) so the\\n  /vitest subpath is available. Keep jest-when on jest-when@^3.x: its\\n  fluent API works against vitest's vi.fn() unchanged because vitest\\n  mocks are jest-API-compatible.\\n- Add vitest.config.ts: jsdom environment, .scss/.css aliased to\\n  identity-obj-proxy via the anchored ^.*\\\\.s?css$ regex,\\n  @openmrs/esm-framework aliased to its mock, react-i18next and\\n  react-markdown aliased to their local __mocks__ files,\\n  __mocks__/* and src/* aliased so the bare imports the jest\\n  config used to resolve via moduleDirectories continue to work,\\n  and fakeTimers.toFake limited so it does not break React's\\n  scheduler.\\n- Replace src/setup-tests.ts's '@testing-library/jest-dom' import\\n  with '@testing-library/jest-dom/vitest', drop the 'jest-when'\\n  side-effect import (no longer needed), swap jest.fn for vi.fn in\\n  the i18next mock, and convert the require('resize-observer-polyfill')\\n  call to a proper ESM import.\\n- Rewrite __mocks__/react-i18next.js's I18nextProvider entry to a\\n  plain function component, since the previous jest.fn() call only\\n  worked under jest's globals.\\n- Convert the 41 test files to the vitest API: explicit imports for\\n  describe/expect/it/test/vi (plus beforeEach/afterEach/type Mock\\n  where used), jest.* swapped for vi.*. The many vi.mock(path, ...\\n  jest.requireActual(path), override) factories rewritten as the\\n  async vi.mock(path, async () => ({ ...((await vi.importActual(path))\\n  as object), override })) form. The vi.mock(name, () => vi.fn())\\n  factory wrapped in { default: vi.fn() }. The jest.requireMock call\\n  in usePostSubmissionActions.test.tsx replaced with vi.mocked over\\n  a direct import. The pre-existing xdescribe rewritten as\\n  describe.skip. fail() calls swapped for expect.fail().\\n  vi.spyOn(...).mockImplementation() calls passed an explicit\\n  () => {} since vitest's mockImplementation requires an argument.\\n- Skip 8 tests that were exercising Carbon UiSelectExtended or\\n  fake-timer + ART-month-calc flows; they appear to depend on\\n  jest-fake-timers semantics or Carbon DOM details that do not\\n  reproduce in jsdom under vitest. Each carries a TODO comment for\\n  follow-up. The remaining 343 tests pass.\\n- Delete jest.config.js.\\n\\n343 tests pass (20 skipped, 12 of which were skipped pre-existing).\\nLint and typescript checks are green.\\n\\n* (chore) Use fileURLToPath for vitest config aliases\\n\\nnew URL('./path', import.meta.url).pathname returns /C:/Users/... on\\nWindows, which is not a valid filesystem path for Node's fs or\\npath.resolve. The seven alias replacements in vitest.config.ts all\\nrelied on .pathname, so the test suite would have silently broken for\\nWindows contributors.\\n\\nAdd a small helper that wraps fileURLToPath so each call site stays\\nreadable, and route every URL-based path through it.\\n\\nAlso update tsconfig.json to include vitest.config.ts and drop the\\nstale references to setupTests.ts (the actual file lives under src/)\\nand jest.config.js (deleted in this PR). Without vitest.config.ts in\\nthe include list, typed eslint refuses to lint it.\\n\\n* (chore) Document why specific tests are skipped during vitest migration\\n\\nFive tests / blocks were skipped during the jest-to-vitest migration\\nwithout an inline marker explaining the symptom or who is expected to\\nunskip them. Add a TODO comment above each:\\n\\n- ui-select-extended 'Enter/New mode' and 'Edit mode': the Carbon\\n  UiSelectExtended combobox no longer exposes its options to the\\n  accessible-name queries the tests rely on under jsdom +\\n  @testing-library/react 16.\\n- form-engine 'should evaluate months on ART': the test wired up\\n  jest-fake-timers' doNotFake option, which vitest's fakeTimers API\\n  does not provide a direct equivalent for.\\n- form-engine 'should save diagnosis field on form submission' and\\n  'should edit diagnosis field on form submission': the Carbon\\n  combobox in the diagnosis-search workspace has the same option\\n  discoverability issue as ui-select-extended.\\n\\nNo behaviour change; comments only.\\n\\n* (chore) Move setup-tests.ts out of src/ into tools/\\n\\nPer review feedback: this file is test infrastructure, not library\\nsource, so it doesn't belong under src/. Matches the convention used in\\nother recent PRs in this repo.\\n\\n- src/setup-tests.ts → tools/setup-tests.ts\\n- vitest.config.ts: setupFiles path updated\\n- tsconfig.json: add tools/setup-tests.ts to include (the previous\\n  src/**/* glob picked it up; now it's outside that glob)\\n- package.json: drop the now-redundant \\\"!src/setup-tests.ts\\\" files\\n  exclusion (the file is no longer in src/)\\n\\nThe build script's \\\"--ignore '**/setup-tests.*'\\\" pattern and\\ntsconfig.build.json's exclude pattern still match by basename, so no\\nchange there.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"22dcd6a117422f3d3bbb58b62f9d5ef1a34a9f01\",\"date\":\"2026-05-05T23:11:37-07:00\",\"message\":\"(test) O3-3940: Add test coverage for the useEvaluateFormFieldExpressions hook (#537)\",\"refs\":\"\",\"body\":\"- tests field's hidden, required, disabled, readOnly\\n- tests field's questionOpts hidden and disabled\\n- test some extra edge cases for hide/siable/readonly default values, etc\\n\\nCo-authored-by: Pius Rubangakene <piruville@gmail.com>\",\"authorName\":\"ngngo0\",\"authorEmail\":\"97553043+ngngo0@users.noreply.github.com\"},{\"hash\":\"5e2724dbeadbb160a0ddec112aff262c9ab96f95\",\"date\":\"2026-05-06T07:56:31+03:00\",\"message\":\"(feat) O3-4607: Add getLatestObsForConceptSet helper for multi-checkbox observations (#734)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Josephkagimu1\",\"authorEmail\":\"88326256+Josephkagimu1@users.noreply.github.com\"},{\"hash\":\"f700e4e9f2cd65a2be75391126c84da6e49c79fe\",\"date\":\"2026-04-30T12:35:11+03:00\",\"message\":\"(feat) Expand markdown allowlist for richer explanatory content (#733)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"aa7a4be159098231708a79a3d25a1e0f64d15a34\",\"date\":\"2026-04-22T14:40:06+05:30\",\"message\":\"(feat) O3-4795: Show character counter when maxLength is set on textarea fields (#729)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ash\",\"authorEmail\":\"aishwarya.tripathi2023@vitstudent.ac.in\"},{\"hash\":\"dd7cd343082b614b8efb0c0de030e536dd31bcd0\",\"date\":\"2026-04-22T01:34:53+05:30\",\"message\":\"(feat) O3-4795: Show character counter when maxLength is set on text fields (#725)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ash\",\"authorEmail\":\"aishwarya.tripathi2023@vitstudent.ac.in\"},{\"hash\":\"104aa5c1669967834591d1f921acc04c1b2d3092\",\"date\":\"2026-04-21T22:46:37+03:00\",\"message\":\"(fix) Avoid suffix collision when adding a row after deleting a middle one (#728)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"2c0bdceb01a64cd5843f2e3e872b1bdc50f8a272\",\"date\":\"2026-04-21T21:50:06+03:00\",\"message\":\"(fix) Clear RHF state when deleting a repeat-group row (#726)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"108a37b80f0b6c864b9f1b19cb419f761b4f8741\",\"date\":\"2026-04-21T17:02:07+03:00\",\"message\":\"(fix) Suffix field ids correctly when they share a prefix in cloned expressions (#727)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":37}"}]}]},"parent_tool_use_id":null,"session_id":"2c8e374f-6e9f-4b78-9042-e4ee8bd8b73a","uuid":"f8dafc5a-881c-4853-b603-0e7caac7e6ba","timestamp":"2026-10-23T04:38:45.482Z","tool_use_result":[{"type":"text","text":"{\"commits\":[{\"hash\":\"b0d8fd2e9a0c68f2c72b2415b6dbf351b6e92c30\",\"date\":\"2026-10-13T16:17:05+05:30\",\"message\":\"(fix) O3-5847: Stop unchanged obs values from creating duplicate obs (#842)\",\"refs\":\"\",\"body\":\"When transformFieldValue received a value equal to the stored obs, it fell\\nthrough to constructObs and submitted a new obs without a uuid, so every save\\nadded a duplicate. It now returns early and submits nothing for an unchanged\\nvalue on a stored obs.\\n\\nhasPreviousObsValueChanged compared date fields with dayjs diff on 'D', which\\ndayjs does not support and treats as milliseconds. It now formats both values\\nwith formatDateByPickerType, the function used for submission, and compares the\\nstrings, so a date counts as changed only when the submitted value changes.\\nformatDateByPickerType falls back to the transformer's defaults when a field\\nhas no datePickerFormat.\\n\\ngetPreviousValue no longer makes the previous encounter's obs the field's own\\nobs, so changing or clearing a previous value in a new encounter no longer\\nupdates or voids the previous encounter's obs.\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"c79bf029d7ce3c51921276c656bea05e82780f4b\",\"date\":\"2026-10-13T15:47:45+05:30\",\"message\":\"(BREAKING) O3-5847: Stop datetime obs shifting a day across timezones (#838)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"ea6bcc897fc95c797df7dbd15abe13b07bbff92f\",\"date\":\"2026-10-13T12:29:56+03:00\",\"message\":\"(fix) Display validation errors for checkbox groups (#840)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Samuel Muli\",\"authorEmail\":\"136758902+Samstar10@users.noreply.github.com\"},{\"hash\":\"c0c4765b1b4224ba9ea3499c4cc77398afa50a73\",\"date\":\"2026-10-12T15:18:37-04:00\",\"message\":\"(fix) Post submission helper should not use eval() (#843)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"129c1f7fd78a83d1b8958ae6dcaa7fe7b51eb143\",\"date\":\"2026-10-08T01:13:57+05:00\",\"message\":\"(fix) O3-6045: Use WHO girls' height-for-age reference and cover month after age 5 (#834)\",\"refs\":\"\",\"body\":\"* (fix) O3-6045: Use WHO girls' height-for-age reference and cover month after age 5\\n\\nhfa_girls_5_above.json was a copy of the boys' table, so girls aged 5 to 17 got height-for-age z-scores against boys' heights. It is now replaced with the table generated from WHO Growth Reference 2007 girls' height-for-age data.\\n\\ngetHeightForAgeRef now uses the under-5 table through day 1,856, where that table ends, and the 5 to 19 year table from month 61 onwards. getBmiForAgeRef uses the 5 to 19 year table from month 61 after day 1,856, so children in the month after their fifth birthday receive valid evaluations instead of null.\\n\\nAdded tests validating table divergence between boys and girls, spot-checking WHO medians against published values, and verifying age transitions.\\n\\n* (fix) O3-6045: Guard weight-for-height scores against invalid birth dates\\n\\nReturn null when the patient's age is unknown instead of selecting an\\nunder-five reference table through the null < 5 comparison.\\n\\nCover missing and invalid birth dates for both sexes in the reference\\nservice and expression helper tests, with the weight-for-height tables\\nloaded before checking the guards.\",\"authorName\":\"Faisal Mehmood\",\"authorEmail\":\"sfm7776@gmail.com\"},{\"hash\":\"bca651cc37683143cadc43e8301cecf806b29738\",\"date\":\"2026-10-07T23:09:52+03:00\",\"message\":\"(test) Wait for the z-score tables before querying the height field (#837)\",\"refs\":\"\",\"body\":\"The first test in zscore-loading.test.tsx pays the cold dynamic import of the WHO\\nreference tables. findByRole gives up after one second, and on the CI runner the\\nimport sometimes takes longer than that, so the test fails with \\\"Unable to find\\nrole=spinbutton\\\" while the form is still showing its loader. It failed that way on\\nmain at 6a5b489 and on both CI runs of #834.\\n\\nThe test now awaits the promise loadZScoreReferences returned before looking for\\nthe height field, so the one-second query timeout starts after the tables are\\nloaded. The later tests in the file run against warm imports, which is why only\\nthis one flakes. With the import delayed by 1.5 seconds locally, the test fails\\nthe same way without this change and passes with it.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"6a5b489b47c58f526f9988624c0bf349ec5b75ad\",\"date\":\"2026-10-07T14:56:38+03:00\",\"message\":\"(fix) O3-6048: Accept numeric string height in calcWeightForHeightZscore (#832)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"solomonfortune\",\"authorEmail\":\"solomonbuwule@gmail.com\"},{\"hash\":\"79f2c23a1a4b3f45103fcd6f63746c87afa6e9fb\",\"date\":\"2026-10-06T22:39:38+05:00\",\"message\":\"(fix) O3-6046: Return null when height is outside reference table or no reference applies (#830)\",\"refs\":\"\",\"body\":\"* (fix) O3-6046: Return null when height is outside reference table or no reference applies\\n\\n* Restore dropped weight-for-height test case\\n\\nThe male age4 case for 95.7 cm and 14 kg was removed along with the\\nout-of-range rows, but the height is inside the reference table and\\nthe expected z-score of '-1' still holds. The matching female case\\nwas kept.\",\"authorName\":\"Faisal Mehmood\",\"authorEmail\":\"sfm7776@gmail.com\"},{\"hash\":\"fcf1b2562d60389dbf88c5383c2d4237d9d1ff8a\",\"date\":\"2026-10-05T15:02:05+03:00\",\"message\":\"(fix) O3-6025: Load z-score tables only when a form needs them (#824)\",\"refs\":\"\",\"body\":\"* (fix) Load z-score reference tables only for forms that use them\\n\\nThe WHO reference tables behind the z-score helpers are about 1.3 MB of JSON, and zscore-service imported all eight of them statically. The form engine app imports registerExpressionHelper from the library's entry at startup, so the tables ended up in its startup chunk, and every form open downloaded and parsed them whether or not the form used a z-score helper.\\n\\nEach table is a dynamic import now. useProcessorDependencies loads the tables for the z-score helpers a form's schema mentions, alongside the processor's own dependencies, so they're in place before initial values or any expression is evaluated. The helpers stay synchronous, because the expression evaluator doesn't await a helper's result before applying an operator to it. getZRefByGenderAndAge is split into one function per reference, so each helper only reads the tables it needs. If a table fails to load, the form still opens, the error is reported, and the helpers that need it return null.\\n\\nuseProcessorDependencies also reports loading from the first render. Once a form has opened, its field adapters and concepts are cached, so initial values could otherwise be computed before the dependencies had started loading.\\n\\nIn esm-form-engine-app the startup chunks go from 1,189 KiB to 382 KiB, or from 301 KiB to 114 KiB gzipped.\\n\\n* (fix) Wait for form dependencies before evaluating growth rules\\n\\n* Keep form state when the schema object changes\\n\\nResetting the form session whenever formJson was a new object wiped\\nentered values in the patient chart. esm-form-engine-app passes a new\\nschema object on every render, and it re-renders once the form is\\nmarked dirty, so the first edit was lost.\\n\\nDrop the session reset in FormFactoryProvider and stop\\nuseProcessorDependencies reloading on a new formJson object. The form\\nbuilder already remounts FormEngine when its schema changes, so no\\nconsumer relies on replacing a mounted schema.\\n\\n* fix: Wait for every subform before allowing submission\\n\\nTrack pending dependencies by form instance so a ready sibling cannot clear another subform’s loading state. Remove the instance from the pending set when it unmounts.\\n\\nCover pending and failed subform dependencies, retry, required-field validation and saving all subforms after recovery.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"0e1edc234479890d45bc09e67b2ee25befc1c803\",\"date\":\"2026-10-05T14:52:41+03:00\",\"message\":\"(fix) O3-6027: Clear order and diagnosis submissions on every write (#826)\",\"refs\":\"\",\"body\":\"* (fix) Clear order and diagnosis submissions on every write\\n\\nOrdersAdapter and EncounterDiagnosisAdapter now clear the field's\\nsubmission at the start of transformFieldValue, the same way ObsAdapter\\nalready does.\\n\\ngracefullySetSubmission only sets values and never clears them, so a\\nnewValue from an earlier write stayed on the field after it was\\ncleared. On a new encounter, selecting an order or diagnosis and then\\nclearing the field still submitted it. On an edited encounter, swapping\\na stored order or diagnosis for another value and then clearing the\\nfield still submitted the swapped value: a NEW order alongside the\\nvoid, or an edit of the stored diagnosis to the swapped concept.\\nClearing first means nothing is submitted for a new encounter and only\\nthe void goes out for an edited one.\\n\\neditOrder no longer needs its own clearSubmission call when the value\\nmatches the stored order, since the submission is already empty.\\n\\n* Fixup\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"ebb02b719931d121419669b531b6e05c77f515e9\",\"date\":\"2026-10-02T21:57:25+03:00\",\"message\":\"(fix) O3-6030: Keep hidden obs group members, orders and diagnoses out of submissions (#822)\",\"refs\":\"\",\"body\":\"* (fix) Keep hidden obs group members, orders and diagnoses out of submissions\\n\\nHide logic only kept hidden top-level obs out of the encounter payload.\\nHidden obs group members, test orders and diagnoses kept whatever value\\nwas entered before the field was hidden, so they were still submitted\\neven though the form no longer showed them.\\n\\nprocessObsGroup now skips hidden members and, in edit mode, voids their\\nstored obs, the same way top-level obs are handled. It reads each\\nmember's visibility and stored obs from the flattened form field,\\nbecause hide evaluation and hydration update that copy rather than the\\none held in the group's questions. prepareOrders and prepareDiagnosis\\nnow skip hidden fields.\\n\\n* Evaluate hide logic for repeated field instances\\n\\nRows added to a repeating field kept their hidden state from when they\\nwere created, so hiding a repeating test order, diagnosis or obs group\\nmember left its extra rows in the encounter payload. Extra group rows\\nalso stayed visible in the form.\\n\\nfindFieldSection looks up the field's page through meta.pageId, which\\nrepeated instances don't carry because cloneRepeatField replaces their\\nmeta. Reading sections off the missing page threw inside the\\nfieldDependents loop in handleFieldLogic, so none of the repeated\\ninstances had their hide expression re-evaluated. It now returns\\nundefined when the page isn't found, which skips the section visibility\\nupdate for repeated instances since they aren't in the form schema.\\n\\n* (fix) Preserve pending deletions for hidden orders and diagnoses\\n\\nFiltering hidden fields out of encounter submissions discarded explicit deletions when a previously cleared field became hidden. Keep pending voided values for hidden orders and diagnoses while excluding their new values. Leave stored values untouched when no deletion is pending, and preserve existing submission behavior for visible fields.\\n\\n* Skip deleted repeated rows when evaluating field dependents\\n\\nDeleting a repeated row removes it from formFields but leaves its id in\\nthe fieldDependents of any field its hide expression references. The\\nnext change to that field made evaluateFieldDependents read\\nquestionOptions off undefined, which threw and stopped the remaining\\ndependents, including other repeated rows, from being re-hidden.\\n\\nevaluateFieldDependents now skips dependent ids that are no longer in\\nformFields.\\n\\n* Keep the stored uuid of nested obs groups\\n\\nprocessObsGroup recursed into nested groups with the copy held in the\\nparent group's questions, which hydration doesn't reach. When a member\\nof a nested group was hidden and nothing else in that group was edited,\\nthe nested group went out without its stored uuid, so the backend\\nwould treat it as a new group rather than update the existing one.\\n\\nThe type check, the recursion and the submission reads now use the\\nflattened form field, the same copy already used for the hidden check.\\nhasSubmittableObs also reuses isFieldHidden instead of repeating the\\ncheck.\\n\\n* Leave hidden swapped orders and diagnoses as they are\\n\\nA swap sets voidedValue alongside newValue, so keeping only voidedValue\\nfor a hidden order turned a replacement into a plain delete: the stored\\norder was voided and nothing replaced it. A hidden diagnosis swapped\\ndirectly was left alone, so the two behaved differently.\\n\\nHidden orders and diagnoses now only submit their voided value when\\nthere's no newValue, which means the field was explicitly cleared.\\nSwapped and reanswered values are left as they are.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"7182a63a48cbf311fb083116b767ad3dc10e3f88\",\"date\":\"2026-09-28T23:31:53+05:30\",\"message\":\"(fix) O3-5963: Improve contrast and anchoring of remove-attachment btn (#816)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Sathieskumar Sudeshkar\",\"authorEmail\":\"sudeshkar008sk@gmail.com\"},{\"hash\":\"dc5422465be8c3ccf4dba4d60977aeb724365b65\",\"date\":\"2026-09-25T14:48:46+03:00\",\"message\":\"(fix) Avoid redundant searches and duplicate field processing (#800)\",\"refs\":\"\",\"body\":\"* fix: debounce searchable select requests\\n\\nKeep the debounce stable across renders and cancel superseded searches.\\nIgnore obsolete responses and cover request lifetime with regression tests.\\n\\n* fix: process field input changes once\\n\\nSkip the watcher echo for values already processed by controls while\\nretaining programmatic updates, array inputs, and historical-value reuse.\\n\\n* fix: stop searchable select requests after selection\\n\\nRead the selected value through a ref so selecting an item does not\\nrestart a search for the previous term. Cancel pending searches and\\ninvalidate in-flight responses when a selection is made.\\n\\nCover synonym matches, pending searches, and responses after selection.\\n\\n* test: tidy the searchable select request tests\\n\\nMove the selection tests into the shared describe block, group the imports,\\nand separate setup, actions, and assertions with blank lines. Drop the manual\\ncleanup call since auto-cleanup already runs, type the wrapper's props as\\nFormField, and pull the repeated combobox change event into a helper.\\n\\nNote why the file drives the input with fireEvent: userEvent waits on a\\nsetTimeout that testing-library only advances under jest's fake timers, so it\\nnever resolves while vitest's fake timers are installed.\\n\\n* fix: read the current selection from form state\\n\\nUse getValues when preserving the selected item in search results. Remove the effect-backed value ref so result handling reads the current form value directly.\\n\\n* fix: validate values entered after unspecified\\n\\nClear the unspecified flag before validating a nonempty value and keep the checkbox synchronized with that flag. This lets the first value run through validation once without relying on effect ordering.\\n\\nCover entering an invalid value in enter and edit modes, correcting it, and reusing a historical value after marking the field unspecified.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"ae1b2b294c2e1a7635bb05f9ed803d7a769496f4\",\"date\":\"2026-09-22T15:51:00-04:00\",\"message\":\"(test) Add tests to cover form submission orchestration (#812)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"8a6e7ea9131cfef56a1c3680bbba47d11bf710fb\",\"date\":\"2026-09-21T18:32:15+03:00\",\"message\":\"(chore) O3-5924: Initialise the root form ref (#810)\",\"refs\":\"\",\"body\":\"Pass undefined explicitly when creating the root form ref. Keep its existing initial value and form registration behaviour while preparing for React 19 types.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"949ad19f6abe33f84a56f623690821c95068628c\",\"date\":\"2026-09-09T17:59:20-04:00\",\"message\":\"(fix) Form engine shouldn't create global CSS rules (#798)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"ad9786412cd423a86c54f889b4e87cf6cf59d61e\",\"date\":\"2026-09-09T12:53:22-04:00\",\"message\":\"(fix) Reduce re-render churn in FormProcessorFactory (#670)\",\"refs\":\"\",\"body\":\"* (fix) Re-write some core hooks in the form-processor-factory to reduce churn\\n\\nIn the FormProcessorFactory, there's serious potential for render\\ncascades from the combinations of `useEffect()` and `setState()` that\\nthen trigger additional `useEffect()` and `setState()` calls. This\\ncommit switches to more aggressively caching some of these key hooks so\\nthat there's less potential for these cascade to lead to catastrophic\\nreloading issues.\\n\\n* Reduce churn in processor context\\n\\nThis is basically done by splitting the processor context into a \\\"static\\\"\\npart that is derived from the form itself and a \\\"dynamic\\\" part that may\\nbe updated by components downstream of the FormProcessorFactory. This\\nmostly should optimize things so that components that depend on the\\nprocessor context should mostly get stable objects, assuming they\\ncorrectly use the properties of the processor.\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"954cee04af4f957d9cea4f57137a63d5a793d021\",\"date\":\"2026-09-09T09:26:06-04:00\",\"message\":\"(feat) Wrap FormEngine in Suspense boundary (#797)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"a6f911cf3612608cac9649229396e0ebc92ae8ba\",\"date\":\"2026-08-20T15:59:32-04:00\",\"message\":\"(test) Add \\\"golden schemas\\\" for encounter payloads (#787)\",\"refs\":\"\",\"body\":\"Co-authored-by: Dennis Kigen <kigen.work@gmail.com>\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"575343c08c8430e8d9de7cd4c137db6a3256c3c4\",\"date\":\"2026-08-19T14:15:05-04:00\",\"message\":\"(test) Create \\\"golden schemas\\\" for Form Schema operations (#784)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"4db319f4ec64190c6197330675a447dd0121f6df\",\"date\":\"2026-08-14T17:42:14-04:00\",\"message\":\"(test) Add scaffolding for better testing (#783)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"fed294cb652b1873f64a738b8b5b7b9424b93189\",\"date\":\"2026-08-12T11:06:00+03:00\",\"message\":\"(chore) Adopt @openmrs/eslint-config and ESLint 9 (#779)\",\"refs\":\"\",\"body\":\"* (chore) Adopt @openmrs/eslint-config and ESLint 9\\n\\nLint config moves to a flat eslint.config.mjs that spreads\\n@openmrs/eslint-config 2.0.0, replacing .eslintrc and .eslintignore. eslint\\nmoves from 8.57 to ^9.39.0 and the --ext flag goes away, since flat config\\nmakes it redundant. The .d.ts ignore is kept, and dist and coverage are\\nnamed explicitly.\\n\\nComparing the effective rule sets before and after, six rules would have\\nbeen lost, so the overlay enforces them again: ban-ts-comment,\\ntriple-slash-reference, no-extra-boolean-cast, no-prototype-builtins,\\nno-unsafe-optional-chaining and no-useless-escape. This repo disabled\\nban-types deliberately, so the rules typescript-eslint v8 split it into stay\\noff, unlike other repos in this migration.\\n\\nThe old config also loaded type information through parserOptions.project\\nwhile enabling no type-aware rules, so that cost goes away with it. Four dev\\ndependencies go with the plugins the shared config provides, including\\neslint-plugin-jsx-a11y, which was declared but never referenced.\\n\\nThe shared config lints tests with testing-library and jest-dom for the\\nfirst time here, which reported 97 problems across the test suite. Sixteen\\nwere autofixes. no-unused-expressions found a real one:\\nexpect(...).toBeInTheDocument was missing its call, so that assertion never\\nran. It passes now that it does. The rule keeps reporting, with\\nallowShortCircuit set, because `x && f()` as a statement is an idiom here.\\n\\nThe remaining 76 are no-unnecessary-act, render-result-naming-convention\\nand no-manual-cleanup. Those need the tests reworked rather than\\nreformatted, so they are off for test files until that happens, and the rest\\nof testing-library applies.\\n\\n__mocks__/index.ts loads JSON fixtures with require(). The shared config\\nexempts __mocks__/**/*.js from no-require-imports but these mocks are\\nTypeScript, so the exemption is repeated here for the directory.\\n\\n* Keep ESLint config out of next updates\\n\\nReplace the @openmrs wildcard with the packages this repository actually tracks on the next tag. This prevents the stable-only ESLint config from breaking the scheduled dependency update workflow.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"a9fdbfc0f5c2a09368c3fb6e777fc3c274629f76\",\"date\":\"2026-07-16T16:02:24+03:00\",\"message\":\"(fix) Only render diagnosis code span when a code exists\",\"refs\":\"\",\"body\":\"Follow-up to #767. Diagnoses without a terminology mapping rendered an\\nempty code span with a reserved 4rem column, indenting their labels to\\nmatch coded entries. Render the code span conditionally instead so\\ncodeless diagnoses display without the placeholder gap.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"208fcc7720fc4f0ca48efb721cf74e7850af2a32\",\"date\":\"2026-07-16T10:03:19+03:00\",\"message\":\"(feat) O3-5815: Show ICD-11 codes next to diagnoses (#767)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"242dbacbaa26c6d6d43f2c12efddda8ed319b99c\",\"date\":\"2026-06-22T20:53:50+05:30\",\"message\":\"(fix) Inline obs date and comment not saved when field visibility is toggled (#759)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"12c24b6731b62e0993ae8ecbe666b13785f71f6e\",\"date\":\"2026-06-12T12:11:44+03:00\",\"message\":\"(fix) O3-5735: Only send default encounter datetimes for stopped visits\",\"refs\":\"\",\"body\":\"PR #756 made new encounters always submit an explicit encounterDatetime,\\nfalling back to the client-clock session date. On browsers running ahead\\nof server time this produces a future datetime that the backend rejects\\nwith Encounter.datetimeShouldBeBeforeCurrent, breaking form submissions\\nin active visits (caught by patient-chart's clock-skew e2e test).\\n\\nRestore the previous behavior for active visits and visit-less encounters:\\nomit encounterDatetime so the backend defaults it to server time. Keep\\nsending the visit-window-clamped session date for stopped visits, which\\nis the retrospective data entry case O3-5735 fixed.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"b99cb4c27946bf936dce89d37baebe31720f8ef8\",\"date\":\"2026-06-11T23:02:01+03:00\",\"message\":\"(fix) O3-5735: Keep default encounter datetimes within the visit window during retrospective data entry (#756)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"bda295eac9755a4df1c22c9c024ea987ccf4d339\",\"date\":\"2026-05-14T01:18:07+03:00\",\"message\":\"(feat) O3-5660: Encounter provider field should auto-fill with current session provider on new forms (#740)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Donald Kibet\",\"authorEmail\":\"chelashawdonald@yahoo.com\"},{\"hash\":\"2204ac05b44795dec06b132c0d15ca1b010bcd95\",\"date\":\"2026-05-13T16:35:49+03:00\",\"message\":\"(chore) Migrate from jest to vitest (#742)\",\"refs\":\"\",\"body\":\"* (chore) Migrate from jest to vitest\\n\\nSwap the test runner from jest to vitest, aligning form-engine-lib\\nwith the patterns adopted across the rest of the O3 apps.\\n\\n- Replace jest, @swc/jest, jest-cli, jest-environment-jsdom, and\\n  @types/jest with vitest, @vitest/coverage-v8, jsdom, and cross-env.\\n  Bump @testing-library/dom (9.x to 10.x), @testing-library/jest-dom\\n  (6.4 to 6.8), and @testing-library/react (14.x to 16.x) so the\\n  /vitest subpath is available. Keep jest-when on jest-when@^3.x: its\\n  fluent API works against vitest's vi.fn() unchanged because vitest\\n  mocks are jest-API-compatible.\\n- Add vitest.config.ts: jsdom environment, .scss/.css aliased to\\n  identity-obj-proxy via the anchored ^.*\\\\.s?css$ regex,\\n  @openmrs/esm-framework aliased to its mock, react-i18next and\\n  react-markdown aliased to their local __mocks__ files,\\n  __mocks__/* and src/* aliased so the bare imports the jest\\n  config used to resolve via moduleDirectories continue to work,\\n  and fakeTimers.toFake limited so it does not break React's\\n  scheduler.\\n- Replace src/setup-tests.ts's '@testing-library/jest-dom' import\\n  with '@testing-library/jest-dom/vitest', drop the 'jest-when'\\n  side-effect import (no longer needed), swap jest.fn for vi.fn in\\n  the i18next mock, and convert the require('resize-observer-polyfill')\\n  call to a proper ESM import.\\n- Rewrite __mocks__/react-i18next.js's I18nextProvider entry to a\\n  plain function component, since the previous jest.fn() call only\\n  worked under jest's globals.\\n- Convert the 41 test files to the vitest API: explicit imports for\\n  describe/expect/it/test/vi (plus beforeEach/afterEach/type Mock\\n  where used), jest.* swapped for vi.*. The many vi.mock(path, ...\\n  jest.requireActual(path), override) factories rewritten as the\\n  async vi.mock(path, async () => ({ ...((await vi.importActual(path))\\n  as object), override })) form. The vi.mock(name, () => vi.fn())\\n  factory wrapped in { default: vi.fn() }. The jest.requireMock call\\n  in usePostSubmissionActions.test.tsx replaced with vi.mocked over\\n  a direct import. The pre-existing xdescribe rewritten as\\n  describe.skip. fail() calls swapped for expect.fail().\\n  vi.spyOn(...).mockImplementation() calls passed an explicit\\n  () => {} since vitest's mockImplementation requires an argument.\\n- Skip 8 tests that were exercising Carbon UiSelectExtended or\\n  fake-timer + ART-month-calc flows; they appear to depend on\\n  jest-fake-timers semantics or Carbon DOM details that do not\\n  reproduce in jsdom under vitest. Each carries a TODO comment for\\n  follow-up. The remaining 343 tests pass.\\n- Delete jest.config.js.\\n\\n343 tests pass (20 skipped, 12 of which were skipped pre-existing).\\nLint and typescript checks are green.\\n\\n* (chore) Use fileURLToPath for vitest config aliases\\n\\nnew URL('./path', import.meta.url).pathname returns /C:/Users/... on\\nWindows, which is not a valid filesystem path for Node's fs or\\npath.resolve. The seven alias replacements in vitest.config.ts all\\nrelied on .pathname, so the test suite would have silently broken for\\nWindows contributors.\\n\\nAdd a small helper that wraps fileURLToPath so each call site stays\\nreadable, and route every URL-based path through it.\\n\\nAlso update tsconfig.json to include vitest.config.ts and drop the\\nstale references to setupTests.ts (the actual file lives under src/)\\nand jest.config.js (deleted in this PR). Without vitest.config.ts in\\nthe include list, typed eslint refuses to lint it.\\n\\n* (chore) Document why specific tests are skipped during vitest migration\\n\\nFive tests / blocks were skipped during the jest-to-vitest migration\\nwithout an inline marker explaining the symptom or who is expected to\\nunskip them. Add a TODO comment above each:\\n\\n- ui-select-extended 'Enter/New mode' and 'Edit mode': the Carbon\\n  UiSelectExtended combobox no longer exposes its options to the\\n  accessible-name queries the tests rely on under jsdom +\\n  @testing-library/react 16.\\n- form-engine 'should evaluate months on ART': the test wired up\\n  jest-fake-timers' doNotFake option, which vitest's fakeTimers API\\n  does not provide a direct equivalent for.\\n- form-engine 'should save diagnosis field on form submission' and\\n  'should edit diagnosis field on form submission': the Carbon\\n  combobox in the diagnosis-search workspace has the same option\\n  discoverability issue as ui-select-extended.\\n\\nNo behaviour change; comments only.\\n\\n* (chore) Move setup-tests.ts out of src/ into tools/\\n\\nPer review feedback: this file is test infrastructure, not library\\nsource, so it doesn't belong under src/. Matches the convention used in\\nother recent PRs in this repo.\\n\\n- src/setup-tests.ts → tools/setup-tests.ts\\n- vitest.config.ts: setupFiles path updated\\n- tsconfig.json: add tools/setup-tests.ts to include (the previous\\n  src/**/* glob picked it up; now it's outside that glob)\\n- package.json: drop the now-redundant \\\"!src/setup-tests.ts\\\" files\\n  exclusion (the file is no longer in src/)\\n\\nThe build script's \\\"--ignore '**/setup-tests.*'\\\" pattern and\\ntsconfig.build.json's exclude pattern still match by basename, so no\\nchange there.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"22dcd6a117422f3d3bbb58b62f9d5ef1a34a9f01\",\"date\":\"2026-05-05T23:11:37-07:00\",\"message\":\"(test) O3-3940: Add test coverage for the useEvaluateFormFieldExpressions hook (#537)\",\"refs\":\"\",\"body\":\"- tests field's hidden, required, disabled, readOnly\\n- tests field's questionOpts hidden and disabled\\n- test some extra edge cases for hide/siable/readonly default values, etc\\n\\nCo-authored-by: Pius Rubangakene <piruville@gmail.com>\",\"authorName\":\"ngngo0\",\"authorEmail\":\"97553043+ngngo0@users.noreply.github.com\"},{\"hash\":\"5e2724dbeadbb160a0ddec112aff262c9ab96f95\",\"date\":\"2026-05-06T07:56:31+03:00\",\"message\":\"(feat) O3-4607: Add getLatestObsForConceptSet helper for multi-checkbox observations (#734)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Josephkagimu1\",\"authorEmail\":\"88326256+Josephkagimu1@users.noreply.github.com\"},{\"hash\":\"f700e4e9f2cd65a2be75391126c84da6e49c79fe\",\"date\":\"2026-04-30T12:35:11+03:00\",\"message\":\"(feat) Expand markdown allowlist for richer explanatory content (#733)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"aa7a4be159098231708a79a3d25a1e0f64d15a34\",\"date\":\"2026-04-22T14:40:06+05:30\",\"message\":\"(feat) O3-4795: Show character counter when maxLength is set on textarea fields (#729)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ash\",\"authorEmail\":\"aishwarya.tripathi2023@vitstudent.ac.in\"},{\"hash\":\"dd7cd343082b614b8efb0c0de030e536dd31bcd0\",\"date\":\"2026-04-22T01:34:53+05:30\",\"message\":\"(feat) O3-4795: Show character counter when maxLength is set on text fields (#725)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ash\",\"authorEmail\":\"aishwarya.tripathi2023@vitstudent.ac.in\"},{\"hash\":\"104aa5c1669967834591d1f921acc04c1b2d3092\",\"date\":\"2026-04-21T22:46:37+03:00\",\"message\":\"(fix) Avoid suffix collision when adding a row after deleting a middle one (#728)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"2c0bdceb01a64cd5843f2e3e872b1bdc50f8a272\",\"date\":\"2026-04-21T21:50:06+03:00\",\"message\":\"(fix) Clear RHF state when deleting a repeat-group row (#726)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"108a37b80f0b6c864b9f1b19cb419f761b4f8741\",\"date\":\"2026-04-21T17:02:07+03:00\",\"message\":\"(fix) Suffix field ids correctly when they share a prefix in cloned expressions (#727)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":37}"}],"tool_result_meta":[{"id":"toolu_011RqbJYfJXXp8CxfJVb82Ch","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
